// 滑動視窗：need 記錄還缺多少，missing 記錄總共還缺幾個字元
// 時間複雜度: O(m + n)，空間複雜度: O(字元集大小)
function minWindow(s, t) {
    const need = new Array(128).fill(0);
    for (const ch of t)
        need[ch.charCodeAt(0)]++;
    let missing = t.length, left = 0, bestStart = 0, bestLen = Infinity;
    for (let right = 0; right < s.length; right++) {
        if (need[s.charCodeAt(right)]-- > 0)
            missing--;
        while (missing === 0) { // 視窗已涵蓋 t，嘗試縮小
            if (right - left + 1 < bestLen) {
                bestStart = left;
                bestLen = right - left + 1;
            }
            if (++need[s.charCodeAt(left++)] > 0)
                missing++;
        }
    }
    return bestLen === Infinity ? '' : s.slice(bestStart, bestStart + bestLen);
}

