#include <string>
#include <unordered_map>
#include <climits>
using namespace std;

class Solution {
public:
    /**
     * 方法：滑動窗口
     * 時間複雜度: O(m + n)
     * 空間複雜度: O(m + n)
     */
    string minWindow(string s, string t) {
        if (s.empty() || t.empty() || s.length() < t.length()) {
            return "";
        }

        // 統計 t 中字符頻率
        unordered_map<char, int> need;
        for (char c : t) {
            need[c]++;
        }
        int required = need.size();

        // 窗口內字符頻率
        unordered_map<char, int> window;
        int formed = 0;

        // 結果
        int minLen = INT_MAX;
        int minLeft = 0;

        // 雙指標
        int left = 0, right = 0;

        while (right < s.length()) {
            // 擴展右邊界
            char c = s[right];
            window[c]++;

            if (need.count(c) && window[c] == need[c]) {
                formed++;
            }

            // 嘗試收縮左邊界
            while (left <= right && formed == required) {
                // 更新結果
                if (right - left + 1 < minLen) {
                    minLen = right - left + 1;
                    minLeft = left;
                }

                // 移除左邊界
                char c = s[left];
                window[c]--;
                if (need.count(c) && window[c] < need[c]) {
                    formed--;
                }

                left++;
            }

            right++;
        }

        return minLen == INT_MAX ? "" : s.substr(minLeft, minLen);
    }
};

