// 滑動視窗：need 記錄還缺多少，missing 記錄總共還缺幾個字元
// 時間複雜度: O(m + n)，空間複雜度: O(1)（固定 128 格）
char* minWindow(char* s, char* t) {
    int need[128] = {0};
    int missing = 0;
    for (char* p = t; *p; p++) { need[(int)*p]++; missing++; }

    int left = 0, bestStart = 0, bestLen = INT_MAX;
    for (int right = 0; s[right]; right++) {
        if (need[(int)s[right]]-- > 0) missing--;
        while (missing == 0) {                        // 視窗已涵蓋 t，嘗試縮小
            if (right - left + 1 < bestLen) {
                bestStart = left;
                bestLen = right - left + 1;
            }
            if (++need[(int)s[left++]] > 0) missing++;
        }
    }
    if (bestLen == INT_MAX) bestLen = 0;
    char* ans = malloc(bestLen + 1);
    memcpy(ans, s + bestStart, bestLen);
    ans[bestLen] = '\0';
    return ans;
}

